package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.entity.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class WarrantyPendingActionPhase2DTest{private final LocalDate today=LocalDate.of(2026,7,20);private final WarrantyPendingActionCalculator calculator=new WarrantyPendingActionCalculator(Clock.fixed(today.atStartOfDay(ZoneId.of("Asia/Kolkata")).toInstant(),ZoneId.of("Asia/Kolkata")));
 @Test void overdueApprovedReplacementRequiresFollowUp(){WarrantyClaim c=claim();c.setState(WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT);c.setExpectedReplacementDate(today.minusDays(1));assertThat(calculator.calculate(c).code()).isEqualTo("FOLLOW_UP_REPLACEMENT");}
 @Test void overrideReplacementRemainsIncomplete(){WarrantyClaim c=claim();c.setState(WarrantyClaimState.REPLACEMENT_RECEIVED);c.setResult(WarrantyClaimResult.REPLACEMENT_DONE);WarrantyReplacement r=new WarrantyReplacement();r.setNewProductName("P");r.setReplacementReferenceNumber("R");assertThat(calculator.calculate(c,r).code()).isEqualTo("COMPLETE_REPLACEMENT_DETAILS");}
 @Test void completeReplacementCanMoveReady(){WarrantyClaim c=claim();c.setState(WarrantyClaimState.REPLACEMENT_RECEIVED);c.setResult(WarrantyClaimResult.REPLACEMENT_DONE);WarrantyReplacement r=new WarrantyReplacement();r.setNewProductName("P");r.setNewSerialNumber("S");r.setReplacementReferenceNumber("R");assertThat(calculator.calculate(c,r).code()).isEqualTo("MOVE_REPLACEMENT_TO_READY_DELIVERY");}
 private WarrantyClaim claim(){WarrantyClaim c=new WarrantyClaim();c.setActive(true);c.setResult(WarrantyClaimResult.PENDING);return c;}}
